export const STRINGS = { ar, en };
export type Strings = typeof ar;

export function num(n: number, lang: Lang): string {
  return new Intl.NumberFormat(lang === 'ar' ? 'ar-EG-u-nu-latn' : 'en-US', { useGrouping: lang !== 'ar' || n >= 10000 }).format(n);
}
